//! Integer prefix costs for the unchanged greedy section merge decisions.
use super::{BOOKS, MAX_BANDS, UNREPRESENTABLE};

// At most 51 finite u32 costs fit below this marker. Its upper bits count
// unrepresentable bands; prefix subtraction preserves both parts exactly.
const MISSING: u64 = 1 << 40;

pub(super) trait Lookup {
    fn range(&self, lo: usize, hi: usize, cb: usize) -> u32;
    fn best(&self, lo: usize, hi: usize) -> Option<(u8, u32)>;
}

// 51 finite u16 costs sum to 3_342_285 <2^22. Including 51 missing-band
// markers, the entire prefix stays below 2^28. No carries mix the fields.
const COMPACT_MISSING: u32 = 1 << 22;

pub(super) struct CompactPrefix {
    values: [[u32; BOOKS]; MAX_BANDS + 1],
}

impl CompactPrefix {
    pub(super) fn try_new(coded: &[bool], bits: &[[u32; BOOKS]], n: usize) -> Option<Self> {
        assert!(n <= MAX_BANDS);
        let mut values = [[0; BOOKS]; MAX_BANDS + 1];
        let mut totals = [0; BOOKS];
        for b in 0..n {
            for ((total, value), &cost) in totals
                .iter_mut()
                .zip(values[b + 1].iter_mut())
                .zip(bits[b].iter())
                .skip(1)
            {
                if coded[b] {
                    *total += if cost == UNREPRESENTABLE {
                        COMPACT_MISSING
                    } else if cost <= u32::from(u16::MAX) {
                        cost
                    } else {
                        return None;
                    };
                }
                *value = *total;
            }
        }
        Some(Self { values })
    }

    fn raw(&self, lo: usize, hi: usize, cb: usize) -> u32 {
        self.values[hi][cb] - self.values[lo][cb]
    }
}

impl Lookup for CompactPrefix {
    fn range(&self, lo: usize, hi: usize, cb: usize) -> u32 {
        let raw = self.raw(lo, hi, cb);
        if raw >= COMPACT_MISSING {
            UNREPRESENTABLE
        } else {
            raw
        }
    }

    fn best(&self, lo: usize, hi: usize) -> Option<(u8, u32)> {
        let mut best = None;
        for cb in 1..BOOKS {
            let raw = self.raw(lo, hi, cb);
            if raw >= COMPACT_MISSING {
                continue;
            }
            if best.is_none_or(|(_, value)| raw < value) {
                best = Some((cb as u8, raw));
            }
        }
        best
    }
}

