/// Choose `sfb_cb` for `n` bands: per-band cheapest book, then greedily
/// merge adjacent coded runs while saved headers outweigh extra spectral
/// bits. ZERO_HCB on uncoded bands. Exact DP is [`plan_books_dp`] (TASK-73
/// no-go as default: < 2% section+spectral savings).
pub(super) fn plan_books_into(
    coded: &[bool],
    bits: &[[u32; BOOKS]],
    n: usize,
    sfb_cb: &mut [u8],
    header_bits: impl Fn(usize) -> usize + Copy,
) {
    let compact = cost::CompactPrefix::try_new(coded, bits, n);
    if let Some(costs) = &compact {
        plan_with_costs(coded, bits, n, sfb_cb, header_bits, costs);
    } else {
        plan_with_wide_costs(coded, bits, n, sfb_cb, header_bits);
    }
}

// Keep the rare arbitrary-large-cost cache out of the common call frame.
#[cold]
#[inline(never)]
fn plan_with_wide_costs(
    coded: &[bool],
    bits: &[[u32; BOOKS]],
    n: usize,
    sfb_cb: &mut [u8],
    header_bits: impl Fn(usize) -> usize + Copy,
) {
    let costs = cost::CostPrefix::new(coded, bits, n);
    plan_with_costs(coded, bits, n, sfb_cb, header_bits, &costs);
}

fn plan_with_costs(
    coded: &[bool],
    bits: &[[u32; BOOKS]],
    n: usize,
    sfb_cb: &mut [u8],
    header_bits: impl Fn(usize) -> usize + Copy,
    costs: &impl cost::Lookup,
) {
    for b in 0..n {
        sfb_cb[b] = if coded[b] {
            best_single_book(&bits[b])
        } else {
            0
        };
    }
    let mut improved = true;
    while improved {
        improved = false;
        let mut lo = 0usize;
        while lo < n {
            if !coded[lo] {
                lo += 1;
                continue;
            }
            let mut hi = lo + 1;
            while hi < n && coded[hi] {
                hi += 1;
            }
            let mut i = lo;
            while i < hi {
                let mut j = i + 1;
                while j < hi && sfb_cb[j] == sfb_cb[i] {
                    j += 1;
                }
                if j < hi {
                    let mut k = j + 1;
                    while k < hi && sfb_cb[k] == sfb_cb[j] {
                        k += 1;
                    }
                    let saved = header_bits(j - i) as i64 + header_bits(k - j) as i64
                        - header_bits(k - i) as i64;
